var RESPONSE_404 = new Response("Not Found", { status: 404 });
var RESPONSE_500 = new Response("Internal Server Error", { status: 500 });
var turboServe = (options) => {
  const port = options.port ?? 3000;
  const hostname = options.hostname ?? "0.0.0.0";
  const server = Bun.serve({
    port,
    hostname,
    fetch: options.fetch,
    error: (error) => {
      options.onError?.(error);
      return RESPONSE_500;
    }
  });
  options.onListen?.({ port, hostname });
  const serverPort = server.port ?? port;
  const serverHostname = server.hostname ?? hostname;
  const stop = () => {
    server.stop();
  };
  return {
    port: serverPort,
    hostname: serverHostname,
    stop
  };
};
